/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=deal, operation=duplicate
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Duplicate a deal */
export type PipedriveV2DealDuplicateParams = {
  resource: 'deal';
  operation: 'duplicate';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the deal to duplicate
 * @default 0
 */
    dealId?: number | Expression<number>;
};

export type PipedriveV2DealDuplicateNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  credentials?: Credentials;
  config: NodeConfig<PipedriveV2DealDuplicateParams>;
};